$GLOBAL
#define MMHG_TO_KPA 0.133322
#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif

// Numerically safe logistic.
double sigf(double x) {
  if (x >  40.0) return 1.0;
  if (x < -40.0) return 0.0;
  return 1.0 / (1.0 + exp(-x));
}

// Smooth max(x,0).  The sharpness matters: see NOTE 7 at the hazard block.
double sp(double x, double k) {
  double z = k * x;
  if (z >  40.0) return x;
  if (z < -40.0) return 0.0;
  return log1p(exp(z)) / k;
}

// Additive competitive occupancy of one receptor by up to three ligands.
double occ3(double c1, double i1, double c2, double i2, double c3, double i3) {
  double e = c1 / i1 + c2 / i2 + c3 / i3;
  return e / (1.0 + e);
}

$ODE
// =========================================================================
//  0.  CONCENTRATIONS AND RECEPTOR OCCUPANCIES
// =========================================================================
double C_ESM  = A_ESM  / V_ESM;
double C_LAB  = A_LABC / V_LAB;
double C_MET  = A_METC / V_MET;
double C_NIC  = A_NICC / V_NIC;
double C_CLV  = A_CLV  / V_CLV;
double C_SNP  = A_SNP  / V_SNP;
double C_CN   = A_CN   / V_CN;
double C_FEN  = A_FENE / V_FEN;
double C_LOS  = A_LOSC / V_LOS;
double C_E31  = A_E3174 / V_E3174;

double OCC_B   = occ3(C_ESM, IC50_ESM, C_LAB, IC50_LABB, C_MET, IC50_MET);
double OCC_A   = occ3(C_LAB, IC50_LABA, 0.0, 1.0, 0.0, 1.0);
double OCC_DHP = occ3(C_NIC, IC50_NIC, C_CLV, IC50_CLV, 0.0, 1.0);
double OCC_NO  = occ3(C_SNP, IC50_SNP, 0.0, 1.0, 0.0, 1.0);
double OCC_OP  = occ3(C_FEN, IC50_FEN, 0.0, 1.0, 0.0, 1.0);
double BLK_AT1 = occ3(C_LOS, IC50_LOS, C_E31, IC50_E3174, 0.0, 1.0);

// =========================================================================
//  1.  SYSTEMIC HAEMODYNAMICS
// =========================================================================
double PRELOAD = (BV / BV0) * (1.0 - 0.25 * OCC_NO) * (1.0 - 0.05 * OCC_DHP);
if (PRELOAD < 0.05) PRELOAD = 0.05;
double SV = SV0 * CTR * pow(PRELOAD, 0.60) * pow(SVR / SVR0, -0.20);
double CO = HR * SV / 1000.0;                                     // L/min

// Vasodilators do not only drop resistance, they raise conduit-artery
// compliance.  Without this term reflex stroke-volume rise blows the pulse
// pressure up and the systolic pressure never falls.
double CART = (CART0 / (1.0 + STIFF * (1.0 - ELN)))
              * (1.0 + 0.25 * OCC_DHP + 0.30 * OCC_NO + 0.10 * OCC_A);
double PP   = SV / CART;
double SBPv = PMAP + 2.0 / 3.0 * PP;
double DBPv = PMAP - 1.0 / 3.0 * PP;

// THE IMPULSE.  Contractility enters with exponent 1, heart rate and afterload
// weakly.  Note what is NOT here: mean pressure.
double DPDTv = DPDT0 * CTR * pow(HR / HR0, EXP_DPDT_HR)
               * pow((DBPv > 15.0 ? DBPv : 15.0) / DBP0, EXP_DPDT_DBP);

// =========================================================================
//  2.  THE DIVIDER
// =========================================================================
double seal      = (TEVAR_T >= 0.0 && SOLVERTIME >= TEVAR_T) ? TEVAR_SEAL : 0.0;
// NOTE 5/6.  Thrombus seals the ENTRY TEAR only when the false lumen is
// essentially completely clotted.  A 40%-thrombosed false lumen still has a
// wide-open entry tear and is still pressurised - that single asymmetry is the
// whole difference between "partial" and "complete" thrombosis.
double seal_thr  = pow(1.0 - sigf((THRFL - SEAL_THR50) / SEAL_THRW), SEAL_POW);
double G_EN      = (AEN / AEN_REF) * seal_thr * (1.0 - seal);
if (G_EN < 0.0) G_EN = 0.0;
double one_thrd  = (1.0 - THRD > 0.0) ? (1.0 - THRD) : 0.0;
double G_RE      = GRE0 * one_thrd * one_thrd;
double GTOT      = G_EN + G_RE;

double tau_fl = (GTOT > 1e-9) ? (TAUFL0 / GTOT) : 1e6;            // seconds
double omega  = 2.0 * M_PI * HR / 60.0;                           // rad/s
double PP_FL  = PP / sqrt(1.0 + omega * omega * tau_fl * tau_fl);
double PFL_SYS = PFL + 2.0 / 3.0 * PP_FL;
double PFL_DIA = PFL - 1.0 / 3.0 * PP_FL;

// Through-flow needs both tears; to-and-fro flow needs only the entry tear and
// is driven by the pressure-AMPLITUDE difference across it, so the harder the
// sac damps the pulse the harder blood is pushed in and out of it.
double gser  = (GTOT > 1e-9) ? (G_EN * G_RE / GTOT) : 0.0;
double dpp   = (PP - PP_FL > 0.0) ? (PP - PP_FL) : 0.0;
double FLOW  = KQ * gser + KTOFRO * G_EN * dpp / 46.0;
double fthr  = 1.0 - KFLOW_THR * THRFL;
FLOW *= (fthr > 0.0 ? fthr : 0.0);

// =========================================================================
//  3.  LAPLACE MECHANICS - AND THE PRODUCT
// =========================================================================
double r_fl   = DFL / 2.0;
double h_eff  = (HFL > 0.05) ? HFL : 0.05;
double SIG_FL     = PFL     * MMHG_TO_KPA * r_fl / h_eff;
double SIG_FL_SYS = PFL_SYS * MMHG_TO_KPA * r_fl / h_eff;
double SIG_TL     = SBPv * MMHG_TO_KPA * (DTL / 2.0) / (HAO0 * (1.0 - FOUT));

// NOTE 5.  The flap only carries stress where it is still a FREE flap: clot
// buttresses it and a stent-graft pins it.  NOTE 6: and its mobility scales
// with how much intima has actually detached, or a 9 mm2 tear feeding a damped
// sac becomes the highest flap stress in the model.
double mobility = pow(AEN / AEN_REF, 0.5);
if (mobility > 1.5) mobility = 1.5;
double exposed  = ((1.0 - THRFL > 0.0) ? (1.0 - THRFL) : 0.0) * (1.0 - seal) * mobility;
double SIG_FLAP = fabs(SBPv - PFL_SYS) * MMHG_TO_KPA * r_fl / 0.25 * exposed;

double ASIv      = (SIG_FL_SYS / SIGREF) * (DPDTv / DPDT0);
double ASI_FLAPv = (SIG_FLAP / SIGREF) * pow(DPDTv / DPDT0, EXP_TEAR_DPDT);

// wall strength and the rupture hazard
double SWALL = SWALL0 * pow((ELN > 0.02 ? ELN : 0.02), EXP_ELN_S) * (0.60 + 0.40 * COL);
double SRv   = SIG_FL_SYS / SWALL;
double earg  = (SRv - 1.0) / W_RUPT;
if (earg > 30.0) earg = 30.0;
double H_RUPT = H0_RUPT * exp(earg);
if (H_RUPT > 0.60) H_RUPT = 0.60;

// wall-thickness set-point: collagen thickens, MMP-9 thins, and mural thrombus
// thins hardest of all (the wall beneath an intraluminal thrombus is hypoxic
// and bathed in neutrophil elastase and plasmin).
double HFL_TGT = (HAO0 * FOUT * (1.0 + HFL_COL * COL))
                 / (1.0 + KH_MMP * sp(MMP9 - 1.0, 8.0) + KTHR_H * THRFL);

// =========================================================================
//  4.  BRANCH PERFUSION
// =========================================================================
// NOTE 3.  Dynamic obstruction needs TWO things at once - a diastolic pressure
// gradient AND false-lumen dominance.  Requiring only the first puts every
// patient in renal failure at t = 0, because a patent false lumen always
// carries mean pressure above true-lumen diastolic pressure.
double flr  = DFL / ((DFL + DTL > 1e-6) ? (DFL + DTL) : 1e-6);
double dom  = (flr - 0.40) / 0.30;
if (dom < 0.0) dom = 0.0;
if (dom > 1.0) dom = 1.0;
double COLLAPSEv = sigf((PFL_DIA - DBPv - 5.0) / 4.0) * dom;
double dyn = KOBST_DYN * COLLAPSEv;

double pat_ren = (1.0 - OBST_REN) * (1.0 - dyn * INV_REN);
double pat_mes = (1.0 - OBST_MES) * (1.0 - dyn * INV_MES);
double pat_spi = (1.0 - OBST_SPI) * (1.0 - 0.55 * COLLAPSEv * INV_SPI);
if (pat_ren < 0.02) pat_ren = 0.02;
if (pat_mes < 0.02) pat_mes = 0.02;
if (pat_spi < 0.02) pat_spi = 0.02;
double cover = (TEVAR_T >= 0.0 && SOLVERTIME >= TEVAR_T) ? TEVAR_COVER : 0.0;
double spi_loss = 1.0 - 0.20 * THRFL - cover;
pat_spi *= (spi_loss > 0.05 ? spi_loss : 0.05);

double PP_REN    = PMAP * pat_ren;
double QREN_INST = 0.04 + 1.02 * sigf((PP_REN - 58.0) / 8.5);
if (QREN_INST > 1.06) QREN_INST = 1.06;
double QMES = 0.04 + 1.02 * sigf((PMAP * pat_mes - 52.0) / 8.0);
if (QMES > 1.06) QMES = 1.06;
double SCPP = PMAP - SCP_CSF;
// NOTE 8.  Collaterals SUBSTITUTE for lost segmental supply; they are also
// recruitable, which is why paraplegia is an acute-window risk rather than a
// permanent state, and why staged coverage works.
double scpp_eff = SCPP * (pat_spi + KCOL_SPI * COLLAT * (1.0 - pat_spi));
double QSPI = 0.04 + 1.02 * sigf((scpp_eff - SCPP50) / 7.0);
if (QSPI > 1.06) QSPI = 1.06;

// =========================================================================
//  5.  INFUSION RATES (fixed plus closed-loop titration)
// =========================================================================
// A nurse titrating to a systolic target is an integral controller.  Writing it
// this way lets the arms be compared AT THE SAME ACHIEVED PRESSURE, which is
// the only fair way to ask what a vasodilator costs.
double u_vd = VD_MAX * sigf(U_VD);
double u_bb = BB_MAX * sigf(U_BB);
double r_esm = R_ESM + ((BB_AGENT > 0.5 && BB_AGENT < 1.5) ? u_bb : 0.0);
double r_lab = R_LAB + ((BB_AGENT > 1.5) ? u_bb : 0.0);
double r_nic = R_NIC + ((VD_AGENT > 0.5 && VD_AGENT < 1.5) ? u_vd : 0.0);
double r_clv = R_CLV + ((VD_AGENT > 1.5 && VD_AGENT < 2.5) ? u_vd : 0.0);
double r_snp = R_SNP + ((VD_AGENT > 2.5) ? u_vd : 0.0);

// =========================================================================
//  6.  THE 53 DIFFERENTIAL EQUATIONS
// =========================================================================
// ---- drug pharmacokinetics ----------------------------------------------
dxdt_A_ESM  = r_esm - CL_ESM / V_ESM * A_ESM;
dxdt_A_LABC = r_lab - CL_LAB / V_LAB * A_LABC
              - Q_LAB / V_LAB * A_LABC + Q_LAB / V_LAB2 * A_LABP;
dxdt_A_LABP = Q_LAB / V_LAB * A_LABC - Q_LAB / V_LAB2 * A_LABP;
// oral maintenance drugs are given as an equivalent continuous rate: the
// peak-trough ripple is irrelevant to a five-year growth curve
dxdt_A_METD = D_MET * ADHERE / TAU_PO - KA_MET * A_METD;
dxdt_A_METC = F_MET * KA_MET * A_METD - CL_MET / V_MET * A_METC;
dxdt_A_NICC = r_nic - CL_NIC / V_NIC * A_NICC
              - Q_NIC / V_NIC * A_NICC + Q_NIC / V_NIC2 * A_NICP;
dxdt_A_NICP = Q_NIC / V_NIC * A_NICC - Q_NIC / V_NIC2 * A_NICP;
dxdt_A_CLV  = r_clv - CL_CLV / V_CLV * A_CLV;
dxdt_A_SNP  = r_snp - CL_SNP / V_SNP * A_SNP;
// every molecule of nitroprusside that is cleared liberates five cyanide ions
dxdt_A_CN   = FCN * CL_SNP / V_SNP * A_SNP - CL_CN / V_CN * A_CN;
// rhodanese makes thiocyanate, which the kidney has to excrete - and the
// kidney is exactly what a dissection threatens
dxdt_A_SCN  = CL_CN / V_CN * A_CN * 2.23
              - CL_SCN * ((QREN > 0.05) ? QREN : 0.05) / V_SCN * A_SCN;
dxdt_A_FENC = R_FEN - CL_FEN / V_FEN * A_FENC;
dxdt_A_FENE = KE0_FEN * (A_FENC - A_FENE);
dxdt_A_LOSD = D_LOS * ADHERE / TAU_PO - KA_LOS * A_LOSD;
dxdt_A_LOSC = F_LOS * KA_LOS * A_LOSD - CL_LOS / V_LOS * A_LOSC;
dxdt_A_E3174= FM_LOS * CL_LOS / V_LOS * A_LOSC - CL_E3174 / V_E3174 * A_E3174;

// ---- baroreflex and sympathetic outflow ---------------------------------
double baro   = 1.0 + KBARO * (BAROSET - PMAP) / BAROSET;
double ang_ex = sp(ANGII - 1.0, 8.0);
double sna_t  = SNA0 * sp(baro, 6.0)
                * (1.0 + KPAIN * PAIN / 10.0)
                * (1.0 + KANG * ang_ex * (1.0 - BLK_AT1));
dxdt_SNA = (sna_t - SNA) / TAU_SNA;
// NOTE 2.  Resetting is PARTIAL.  Let the operating point track mean pressure
// completely and the reflex forgets the pressure it is meant to defend: the
// untreated arm then walks its own MAP past 160 mmHg with no equilibrium.
double baro_tgt = (1.0 - FRESET) * BARO_REF + FRESET * PMAP;
dxdt_BAROSET = (baro_tgt - BAROSET) / TAU_BARO;

// ---- heart, vessels, pressure -------------------------------------------
double sna_r = (SNA / SNA0 > 0.02) ? (SNA / SNA0) : 0.02;
double hr_t  = HR0 * pow(sna_r, EXP_HR_SNA) * (1.0 - EMAX_BB_HR * OCC_B);
dxdt_HR = ((hr_t > 32.0 ? hr_t : 32.0) - HR) / TAU_HR;
double ctr_t = CTR0 * pow(sna_r, EXP_CTR_SNA) * (1.0 - EMAX_BB_CTR * OCC_B);
dxdt_CTR = ((ctr_t > 0.25 ? ctr_t : 0.25) - CTR) / TAU_CTR;
double svr_t = SVR0 * pow(sna_r, EXP_SVR_SNA)
               * (1.0 - EMAX_DHP * OCC_DHP)
               * (1.0 - EMAX_ALPHA * OCC_A)
               * (1.0 - EMAX_NO * OCC_NO)
               * (1.0 + 0.30 * ang_ex * (1.0 - BLK_AT1))
               * (1.0 - EMAX_AT1 * BLK_AT1);
dxdt_SVR = ((svr_t > 3.0 ? svr_t : 3.0) - SVR) / TAU_SVR;
dxdt_PMAP = (CO * SVR + 5.0 - PMAP) / TAU_MAP;

// ---- RAAS and volume ----------------------------------------------------
double qren_s = (QREN > 0.05) ? QREN : 0.05;
double pra_t  = (1.0 + KRENIN * (1.0 / qren_s - 1.0))
                * (1.0 - EMAX_BB_RENIN * OCC_B)
                * (1.0 + KAT1FB * BLK_AT1);
dxdt_PRA   = ((pra_t > 0.05 ? pra_t : 0.05) - PRA) / TAU_PRA;
dxdt_ANGII = (PRA - ANGII) / TAU_ANG;
double aldo_t = 1.0 + 0.9 * (ANGII * (1.0 - BLK_AT1) - 1.0);
dxdt_ALDO = ((aldo_t > 0.1 ? aldo_t : 0.1) - ALDO) / TAU_ALDO;
dxdt_BV = (BV0 * (1.0 + KALDO_BV * (ALDO - 1.0)) - BV) / TAU_BV;

// ---- the two-lumen divider ---------------------------------------------
double pdist = PMAP - DPAO;
dxdt_PFL = KCOMM * (G_EN * (PMAP - PFL) + G_RE * (pdist - PFL))
           - KDEP * (PFL - PVEN);
dxdt_DTL = (DTL0 * (1.0 - KCOLLAPSE * COLLAPSEv) - DTL) / TAU_DTL;

// The mechanotransduced signal, saturating.  NOTE 1: left linear in wall
// stress it closes an unbounded stress -> IL-6 -> MMP-9 -> thinning -> stress
// loop, and the five-year run reaches MMP-9 44x normal on a 0.16 mm wall.
double xs = sp(SIG_FL_SYS / SIGREF - 1.0, 8.0);
double xs_sat = xs / (1.0 + xs);

// False-lumen expansion.  Stress enters with the Laplace exponent 1.9, so a
// thrombus that thins the wall by factor f multiplies growth by f^1.9 while
// supporting it by only (1 - 0.85*THR).  Exponent against linear term puts the
// growth maximum at an INTERMEDIATE thrombus fraction, closed form
//   THR* = (n*A - s) / ((1+n)*s*A) = 0.426
// for n = EXP_GROW, s = THR_SUPPORT, A = KTHR_H.  Nothing in this file says
// partial thrombosis is dangerous; this line makes it so.
double capf  = 1.0 - sigf((DFL - DFL_CAP) / 1.5);
double grow  = KGROW * pow(SIG_FL / SIGREF, EXP_GROW)
               * (1.0 + KMMP_GROW * sp(MMP9 - 1.0, 8.0))
               * (1.0 - THR_SUPPORT * THRFL) * capf;
double regress = KREGRESS * THRFL * sigf((25.0 - PFL) / 6.0);
dxdt_DFL = grow - regress;

double stasis   = 1.0 / (1.0 + pow(FLOW / FLOW50, 2.0));
double stasis_d = 1.0 / (1.0 + pow(FLOW / FLOW50D, 2.0));
double flow_c   = (FLOW < 3.0) ? FLOW : 3.0;
dxdt_THRFL = KTHR * stasis * (1.0 - THRFL) - KLYS * THRFL * flow_c;
dxdt_THRD  = KTHRD * stasis_d * (1.0 - THRD) - KLYSD * THRD * flow_c;

// Entry tear propagation: the place the product earns its keep.  A regimen is
// aorta-protective if and only if it drives ASI_flap below TEAR_TH - which a
// beta-blocker does by lowering BOTH factors, and which a vasodilator can fail
// to do even while lowering the pressure, because it raises the second one.
double tear_head = 1.0 - AEN / AEN_MAX;
if (tear_head < 0.0) tear_head = 0.0;
dxdt_AEN = KTEAR * AEN * sp(ASI_FLAPv - TEAR_TH, 40.0) * tear_head
           / (1.0 + 3.0 * COL)
           - KHEAL_TEAR * COL * sp(AEN - 0.6 * AEN0, 8.0);

dxdt_HFL = KREM_H * (HFL_TGT - HFL);
dxdt_ELN = -KELN * sp(MMP9 - 1.0, 8.0) * ELN;
// NOTE 4.  Stress-driven adventitial collagen is the ONLY negative feedback
// the aorta has: a thicker outer wall lowers sigma = P*r/h.  Without it the
// model has no stable chronic state at all.
double col_head = 1.0 - COL / COLMAX;
if (col_head < 0.0) col_head = 0.0;
dxdt_COL = (KCOL * (0.10 + sp(TGFB - 1.0, 8.0)) + KCOL_STRESS * xs) * col_head
           - KDEGC * COL * MMP9;

// ---- injury, inflammation, pain ----------------------------------------
dxdt_INJ = -INJ / TAU_INJ;
dxdt_IL6 = KIL6 * INJ + KIL6_STRESS * xs_sat - KOUT_IL6 * (IL6 - 1.0);
// MMP-9 and TGF-beta are set-point relaxations, so a healthy input of 1.0
// returns exactly 1.0.  The first version had production terms that did not
// balance their own baselines, and the model diverged.
double mmp_t = GEN_MMP * (1.0 + KMMP_IL6 * sp(IL6 - 1.0, 8.0))
               * (1.0 + KMMP_AT1 * sp(ANGII * (1.0 - BLK_AT1) - 1.0, 8.0));
dxdt_MMP9 = KOUT_MMP * (mmp_t - MMP9);
double tgf_t = (1.0 + KTGF_INJ * INJ + KTGF_MMP * sp(MMP9 - 1.0, 8.0))
               * (0.40 + 0.60 * (1.0 - BLK_AT1));
dxdt_TGFB = KOUT_TGF * (tgf_t - TGFB);

// NOTE 9.  Pain from wall stress is gated by flap friability: the tearing pain
// of onset is the injury signal, what persists is stress on a FRESH flap.  A
// chronic remodelled dissection is painless, and letting it hurt gave the model
// a phantom sympathetic cause of chronic hypertension.
double friab  = 1.0 / (1.0 + 4.0 * COL);
double pain_t = KPAIN_INJ * INJ
                + 10.0 * sigf((SIG_FL_SYS / SIG_PAIN - 1.0) / 0.16)
                * (0.15 + 0.85 * friab);
if (pain_t > 10.0) pain_t = 10.0;
pain_t *= (1.0 - EMAX_OP * OCC_OP);
dxdt_PAIN = (pain_t - PAIN) / TAU_PAIN;

// ---- organ perfusion and laboratory endpoints --------------------------
dxdt_QREN  = (QREN_INST - QREN) / TAU_QREN;
dxdt_CREAT = (CREAT_PROD - CL_CREAT0 * ((QREN > 0.03) ? QREN : 0.03) * CREAT)
             / V_CREAT * 24.0;
dxdt_LACT  = KLACT_MES * sp(0.85 - QMES, 8.0)
             + KLACT_CN * sp(C_CN - 0.35, 8.0)
             - KOUT_LACT * (LACT - LACT0);
dxdt_SCI   = KSCI * sp(SCI_THRESH - QSPI, 8.0) - SCI / TAU_SCI;
dxdt_COLLAT= KCOLL * sp(0.75 - QSPI, 8.0) * (1.0 - COLLAT) - KCOLL_D * COLLAT;
dxdt_DDIM  = KDD_FLOW * FLOW * (1.0 - THRFL)
             + KDD_THR * sp(dxdt_THRFL * 100.0, 8.0) * 0.1
             - KOUT_DD * (DDIM - DDIM0);

// ---- outcome integrals --------------------------------------------------
// NOTE 7.  The sharpness arguments here are not cosmetic.  With the default
// smoothing the softplus tail returns ~0.004 for an argument of -0.43, so a
// perfectly perfused organ contributed 1.05e-5/h of hazard - four times the
// whole non-aortic mortality - and over 43 800 h that numerical leak, not any
// modelled mechanism, became the leading cause of death in every chronic arm.
double h_mal = KH_MALPERF * (sp(0.55 - QMES, 40.0) + sp(0.45 - QREN, 40.0));
// Death in the acute phase is mostly not free-wall rupture, it is extension -
// retrograde into the arch or distally into a new branch - so the hazard
// carries a term proportional to how hard the flap is being driven, gated by
// flap friability (acute flap friable, chronic flap fibrotic).
double h_ext = KH_EXT * sp(ASI_FLAPv - TEAR_TH, 40.0)
               * (0.25 + 0.75 * INJ) / (1.0 + 4.0 * COL);
double h_tot = H_RUPT + h_mal + h_ext + KH_OTHER;
dxdt_CUMH = H_RUPT + h_ext;
dxdt_SURV = -h_tot * SURV;
dxdt_DAM  = ASIv;
dxdt_TIT  = sigf((SBPv - SBP_LO) / 2.0) * sigf((SBP_HI - SBPv) / 2.0)
            * sigf((HR_TGT + 5.0 - HR) / 2.0);
dxdt_AUCASI = ASIv;

// ---- closed-loop titration ---------------------------------------------
dxdt_U_VD = (VD_MAX > 0.0) ? KI_VD * (SBPv - SBP_SET) : 0.0;
if (BB_MAX > 0.0) {
  dxdt_U_BB = (BB_ON_SBP > 0.5) ? KI_BB_SBP * (SBPv - SBP_SET)
                                : KI_BB * (HR - HR_SET);
} else {
  dxdt_U_BB = 0.0;
}

$TABLE
double C_ESMo = A_ESM / V_ESM;
double C_NICo = A_NICC / V_NIC;
double C_SNPo = A_SNP / V_SNP;
double C_LABo = A_LABC / V_LAB;
double C_CLVo = A_CLV / V_CLV;
double C_CNo  = A_CN / V_CN;
double C_SCNo = A_SCN / V_SCN;
double C_METo = A_METC / V_MET;
double C_E31o = A_E3174 / V_E3174;
double C_FENo = A_FENE / V_FEN;

double OCC_Bo   = occ3(C_ESMo, IC50_ESM, C_LABo, IC50_LABB, C_METo, IC50_MET);
double OCC_Ao   = occ3(C_LABo, IC50_LABA, 0.0, 1.0, 0.0, 1.0);
double OCC_DHPo = occ3(C_NICo, IC50_NIC, C_CLVo, IC50_CLV, 0.0, 1.0);
double OCC_NOo  = occ3(C_SNPo, IC50_SNP, 0.0, 1.0, 0.0, 1.0);
double BLK_AT1o = occ3(A_LOSC / V_LOS, IC50_LOS, C_E31o, IC50_E3174, 0.0, 1.0);

double PRELOADo = (BV / BV0) * (1.0 - 0.25 * OCC_NOo) * (1.0 - 0.05 * OCC_DHPo);
if (PRELOADo < 0.05) PRELOADo = 0.05;
double SVo   = SV0 * CTR * pow(PRELOADo, 0.60) * pow(SVR / SVR0, -0.20);
double COo   = HR * SVo / 1000.0;
double CARTo = (CART0 / (1.0 + STIFF * (1.0 - ELN)))
               * (1.0 + 0.25 * OCC_DHPo + 0.30 * OCC_NOo + 0.10 * OCC_Ao);
double PPo   = SVo / CARTo;

capture SBP  = PMAP + 2.0 / 3.0 * PPo;
capture DBP  = PMAP - 1.0 / 3.0 * PPo;
capture MAP  = PMAP;
capture PULSE_PRESSURE = PPo;
capture CARDIAC_OUTPUT = COo;
capture STROKE_VOLUME  = SVo;
capture DPDT = DPDT0 * CTR * pow(HR / HR0, EXP_DPDT_HR)
               * pow(((PMAP - PPo / 3.0) > 15.0 ? (PMAP - PPo / 3.0) : 15.0) / DBP0,
                     EXP_DPDT_DBP);

double sealo     = (TEVAR_T >= 0.0 && SOLVERTIME >= TEVAR_T) ? TEVAR_SEAL : 0.0;
double seal_thro = pow(1.0 - sigf((THRFL - SEAL_THR50) / SEAL_THRW), SEAL_POW);
capture G_ENTRY  = (AEN / AEN_REF) * seal_thro * (1.0 - sealo);
double one_thrdo = (1.0 - THRD > 0.0) ? (1.0 - THRD) : 0.0;
capture G_REENTRY = GRE0 * one_thrdo * one_thrdo;
double GTOTo = G_ENTRY + G_REENTRY;
capture TAU_FL = (GTOTo > 1e-9) ? (TAUFL0 / GTOTo) : 1e6;
double omegao  = 2.0 * M_PI * HR / 60.0;
capture PP_FALSE = PPo / sqrt(1.0 + omegao * omegao * TAU_FL * TAU_FL);
capture PFL_SYSTOLIC  = PFL + 2.0 / 3.0 * PP_FALSE;
capture PFL_DIASTOLIC = PFL - 1.0 / 3.0 * PP_FALSE;
double gsero = (GTOTo > 1e-9) ? (G_ENTRY * G_REENTRY / GTOTo) : 0.0;
double dppo  = (PPo - PP_FALSE > 0.0) ? (PPo - PP_FALSE) : 0.0;
double fthro = 1.0 - KFLOW_THR * THRFL;
capture FLOW_FALSE = (KQ * gsero + KTOFRO * G_ENTRY * dppo / 46.0)
                     * (fthro > 0.0 ? fthro : 0.0);

double h_effo = (HFL > 0.05) ? HFL : 0.05;
capture SIGMA_FL     = PFL * MMHG_TO_KPA * (DFL / 2.0) / h_effo;
capture SIGMA_FL_SYS = PFL_SYSTOLIC * MMHG_TO_KPA * (DFL / 2.0) / h_effo;
capture SIGMA_TL     = SBP * MMHG_TO_KPA * (DTL / 2.0) / (HAO0 * (1.0 - FOUT));
double mobo = pow(AEN / AEN_REF, 0.5);
if (mobo > 1.5) mobo = 1.5;
double expo = ((1.0 - THRFL > 0.0) ? (1.0 - THRFL) : 0.0) * (1.0 - sealo) * mobo;
capture SIGMA_FLAP = fabs(SBP - PFL_SYSTOLIC) * MMHG_TO_KPA * (DFL / 2.0) / 0.25 * expo;

// THE INDEX, and the flap index that carries the propagation threshold
capture ASI      = (SIGMA_FL_SYS / SIGREF) * (DPDT / DPDT0);
capture ASI_FLAP = (SIGMA_FLAP / SIGREF) * pow(DPDT / DPDT0, EXP_TEAR_DPDT);
capture ABOVE_TEAR_THRESHOLD = (ASI_FLAP > TEAR_TH) ? 1.0 : 0.0;

capture WALL_STRENGTH = SWALL0 * pow((ELN > 0.02 ? ELN : 0.02), EXP_ELN_S)
                        * (0.60 + 0.40 * COL);
capture STRESS_RATIO  = SIGMA_FL_SYS / WALL_STRENGTH;
capture D_AORTA       = sqrt(DTL * DTL + DFL * DFL);
capture FL_FRACTION   = DFL / ((DFL + DTL > 1e-6) ? (DFL + DTL) : 1e-6);

double flro = FL_FRACTION;
double domo = (flro - 0.40) / 0.30;
if (domo < 0.0) domo = 0.0;
if (domo > 1.0) domo = 1.0;
capture TL_COLLAPSE = sigf((PFL_DIASTOLIC - DBP - 5.0) / 4.0) * domo;
double dyno = KOBST_DYN * TL_COLLAPSE;
double pat_reno = (1.0 - OBST_REN) * (1.0 - dyno * INV_REN);
if (pat_reno < 0.02) pat_reno = 0.02;
capture RENAL_PERFUSION_PRESSURE = PMAP * pat_reno;
double pat_meso = (1.0 - OBST_MES) * (1.0 - dyno * INV_MES);
if (pat_meso < 0.02) pat_meso = 0.02;
capture Q_MESENTERIC = (0.04 + 1.02 * sigf((PMAP * pat_meso - 52.0) / 8.0) > 1.06)
                       ? 1.06 : (0.04 + 1.02 * sigf((PMAP * pat_meso - 52.0) / 8.0));
double pat_spio = (1.0 - OBST_SPI) * (1.0 - 0.55 * TL_COLLAPSE * INV_SPI);
if (pat_spio < 0.02) pat_spio = 0.02;
double covero = (TEVAR_T >= 0.0 && SOLVERTIME >= TEVAR_T) ? TEVAR_COVER : 0.0;
double lsso = 1.0 - 0.20 * THRFL - covero;
pat_spio *= (lsso > 0.05 ? lsso : 0.05);
double scppo = (PMAP - SCP_CSF) * (pat_spio + KCOL_SPI * COLLAT * (1.0 - pat_spio));
capture Q_SPINAL = (0.04 + 1.02 * sigf((scppo - SCPP50) / 7.0) > 1.06)
                   ? 1.06 : (0.04 + 1.02 * sigf((scppo - SCPP50) / 7.0));
capture PARAPLEGIA_PROB = sigf((SCI - SCI_PARA) / 3.0);

capture CYANIDE   = C_CNo;
capture THIOCYANATE = C_SCNo;
capture CYANIDE_TOXIC = (C_CNo > CN_TOX) ? 1.0 : 0.0;
capture EGFR = 175.0 * pow((CREAT > 0.2 ? CREAT : 0.2), -1.154) * pow(65.0, -0.203);
capture IN_TARGET = sigf((SBP - SBP_LO) / 2.0) * sigf((SBP_HI - SBP) / 2.0)
                    * sigf((HR_TGT + 5.0 - HR) / 2.0);
capture OCC_BETA1 = OCC_Bo;
capture OCC_CCB   = OCC_DHPo;
capture OCC_NOD   = OCC_NOo;
capture OCC_AT1   = BLK_AT1o;
capture RATE_VD   = VD_MAX * sigf(U_VD);
capture RATE_BB   = BB_MAX * sigf(U_BB);
capture MORTALITY = 100.0 * (1.0 - SURV);

# =============================================================================
#  CALIBRATION NOTES — what each anchor is, and what it was fitted to
# =============================================================================
#
#  PHARMACOKINETICS.  Esmolol CL 285 mL/kg/min and t1/2 9 min give the 0.70 mg/L
#  plateau at 200 ug/kg/min that the model uses for a 56% beta1 occupancy.
#  Labetalol t1/2 5.4 h with an IV alpha:beta potency ratio of 1:7.  Nicardipine
#  two-compartment with an effective distributive half-life of ~45 min, IC50
#  55 ng/mL.  Clevidipine t1/2 1.7 min (blood esterases) — the drug exists so
#  the vasodilator arm can be switched off in one minute.  Nitroprusside t1/2
#  2 min with stoichiometric cyanide release at 5 CN- per molecule = 0.436 mg
#  CN- per mg SNP, cyanide t1/2 40 min, thiocyanate t1/2 3 days and renally
#  cleared, which is why the model makes renal malperfusion a cyanide risk
#  factor and not just a blood-pressure problem.
#
#  HAEMODYNAMICS.  Reference 65-year-old, 75 kg, treated-but-imperfect
#  hypertension: baroreflex operating point 106 mmHg, HR 62, SVR 17.5, SV 76 mL,
#  arterial compliance 1.72 mL/mmHg, dP/dt max 1180 mmHg/s.  Untreated, the
#  acute arm settles at 154/102 mmHg with HR 71 — IRAD's mean presenting
#  systolic pressure in type B dissection is about 160.
#
#  WALL GEOMETRY.  Descending thoracic wall 1.9 mm; the dissection plane runs in
#  the outer third of the media, so the false-lumen outer wall is 0.40 of that
#  = 0.76 mm, against 1.14 mm for the true lumen.  With r = 8.5 mm and P = 95
#  mmHg that is sigma_FL = 142 kPa, inside the 100-200 kPa range reported for
#  human aortic circumferential stress, and 2.5x the true lumen at the same
#  pressure.  Wall strength 760 kPa fresh.
#
#  GROWTH.  KGROW is set so that a chronically patent false lumen grows the
#  total aortic diameter 3.96 mm/y — reported medically-managed chronic type B
#  growth is 3-4 mm/y with a patent false lumen and under 1 mm/y when it is
#  thrombosed (the model gives -0.2 mm/y, i.e. slow shrinkage of a sealed sac).
#
#  RUPTURE HAZARD.  H0_RUPT and W_RUPT are anchored so that sigma/S = 0.40 (a
#  26 mm dissected aorta at controlled pressure) gives 2%/y and sigma/S = 0.67
#  (a 58 mm one) gives about 11%/y.  KH_OTHER is 2%/y non-aortic mortality.
#
#  WHAT THE MODEL REPRODUCES WITHOUT BEING FITTED TO IT
#  ---------------------------------------------------
#  * Partial false-lumen thrombosis carries the worst prognosis.  Implied hazard
#    ratio versus a patent false lumen 2.36; the adjusted hazard ratio Tsai and
#    colleagues reported from IRAD is 2.69.  The model was given two anatomical
#    numbers, not a hazard ratio.
#  * Vasodilator monotherapy is harmful.  At its labelled ceiling nicardipine
#    lowers systolic pressure 33 mmHg and changes dP/dt max by +0.3%; the entry
#    tear grows 12-13% in 72 h against 1% for an esmolol-first regimen at the
#    same pressure, and 72-h mortality (4.7-5.1%) exceeds giving nothing at all
#    (2.3%).  Every guideline says beta-blockade first; this model says why.
#  * Refractory hypertension in aortic dissection is renal, not pharmacological.
#    The same regimen at the same target reaches SBP 141 with a renal artery off
#    the false lumen and SBP 113 without, with the vasodilator already at its
#    ceiling and renin at 2.5x normal.
#  * Analgesia is an antihypertensive: fentanyl alone takes systolic pressure
#    from 154 to 143 mmHg and dP/dt down 7%.
#
#  WHAT THE MODEL PREDICTS THAT IS NOT ESTABLISHED — TREAT WITH SUSPICION
#  ---------------------------------------------------------------------
#  * Losartan added to a beta-blocked patient does nothing for aortic growth
#    (time to 55 mm 2.00 y without, 1.95 y with).  The mechanism offered is that
#    beta-blockade has already suppressed renin, and what AT1 blockade does
#    reach the wall removes TGF-beta-driven adventitial collagen — the only
#    negative feedback in the model — as fast as it removes Ang II-driven MMP-9.
#    This agrees with the randomised trials that failed to show losartan
#    superior to a beta-blocker, but the cancellation could equally be an
#    artefact of the TGF-beta/collagen coupling.  It is the model's most exposed
#    prediction.
#  * Sustained spinal perfusion-pressure augmentation after coverage halves the
#    cord-ischaemia burden and does not improve five-year survival, because the
#    pressure that perfuses the cord also loads the aorta.  The model's reading
#    is that augmentation belongs to the coverage window and not to the
#    discharge prescription — but the model has no within-window resolution of
#    the cord's tolerance and should not be used to set a duration.
#  * The tear-propagation threshold TEAR_TH = 0.45 is a model construct.  Its
#    existence (a regimen either is or is not above it) is doing a lot of work
#    in the acute-mortality comparison, and no human measurement anchors it.
#
# =============================================================================
